create table if not exists public.routing_execution_logs (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,started_at timestamptz not null,completed_at timestamptz not null,runtime_ms bigint not null check(runtime_ms>=0),total_deficits_analyzed integer not null default 0 check(total_deficits_analyzed>=0),internal_transfers_drafted integer not null default 0 check(internal_transfers_drafted>=0),partial_splits_executed integer not null default 0 check(partial_splits_executed>=0),external_pos_generated integer not null default 0 check(external_pos_generated>=0),bypassed_unit_mismatches integer not null default 0 check(bypassed_unit_mismatches>=0),bypassed_cold_starts integer not null default 0 check(bypassed_cold_starts>=0),created_at timestamptz not null default now());
create index if not exists idx_v20_routing_logs_business_time on public.routing_execution_logs(business_id,created_at desc);
alter table public.supplier_ingredient_terms add column if not exists purchase_unit text;
update public.supplier_ingredient_terms t set purchase_unit=i.base_unit from public.ingredients i where i.id=t.ingredient_id and i.business_id=t.business_id and t.purchase_unit is null;
alter table public.supplier_ingredient_terms alter column purchase_unit set not null;
create index if not exists idx_v20_supplier_terms_route on public.supplier_ingredient_terms(business_id,ingredient_id,supplier_id,active,purchase_unit,effective_from desc);
alter table public.purchase_plan_lines add column if not exists location_id uuid references public.locations(id);
create index if not exists idx_v20_plan_lines_location on public.purchase_plan_lines(business_id,location_id,ingredient_id);
create or replace view public.view_v20_location_reorder as
with daily as (select d.business_id,d.location_id,d.ingredient_id,d.unit,avg(d.consumed_quantity)::numeric(24,8) add_30,max(d.consumed_quantity)::numeric(24,8) max_30,count(*) filter(where d.consumed_quantity>0)::integer history_days from public.ingredient_daily_consumption d where d.location_id is not null and d.demand_date>=current_date-29 group by d.business_id,d.location_id,d.ingredient_id,d.unit),stock as (select * from public.v19_location_stock),selected as (select distinct on (r.business_id,r.ingredient_id) r.business_id,r.ingredient_id,r.supplier_id,r.score from public.supplier_recommendations r where r.recommended order by r.business_id,r.ingredient_id,r.rank,r.score desc,r.supplier_id),terms as (select distinct on (t.business_id,t.ingredient_id,t.supplier_id) t.business_id,t.ingredient_id,t.supplier_id,t.lead_time_days,t.minimum_order_quantity,t.order_multiple,t.purchase_unit from public.supplier_ingredient_terms t where t.active order by t.business_id,t.ingredient_id,t.supplier_id,t.effective_from desc),base as (select l.business_id,l.id location_id,l.code location_code,l.name location_name,i.id ingredient_id,i.name ingredient_name,i.base_unit unit,coalesce(s.current_stock,0)::numeric(24,8) current_stock,coalesce(s.unit_mismatch_count,0)::integer unit_mismatch_count,coalesce(d.add_30,0)::numeric(24,8) average_daily_demand,coalesce(d.max_30,0)::numeric(24,8) maximum_daily_demand,coalesce(d.history_days,0)::integer history_days,(d.ingredient_id is null) cold_start,coalesce(t.lead_time_days,coalesce(f.lead_time_days,0))::numeric(12,4) lead_time_days,greatest(0,(coalesce(d.max_30,0)-coalesce(d.add_30,0))*coalesce(t.lead_time_days,f.lead_time_days,0))::numeric(24,8) safety_stock,coalesce(r.supplier_id,f.supplier_id) supplier_id,coalesce(r.score,f.supplier_score) supplier_score,coalesce(t.minimum_order_quantity,0)::numeric(18,6) minimum_order_quantity,coalesce(t.order_multiple,0)::numeric(18,6) order_multiple,coalesce(t.purchase_unit,i.base_unit) purchase_unit,(coalesce(t.purchase_unit,i.base_unit)=i.base_unit) purchase_unit_exact from public.locations l join public.ingredients i on i.business_id=l.business_id and l.active left join stock s on s.business_id=l.business_id and s.location_id=l.id and s.ingredient_id=i.id left join daily d on d.business_id=l.business_id and d.location_id=l.id and d.ingredient_id=i.id and d.unit=i.base_unit left join selected r on r.business_id=l.business_id and r.ingredient_id=i.id left join public.demand_forecasts f on f.business_id=l.business_id and f.ingredient_id=i.id left join terms t on t.business_id=l.business_id and t.ingredient_id=i.id and t.supplier_id=coalesce(r.supplier_id,f.supplier_id)) select *,greatest(0,average_daily_demand*lead_time_days+safety_stock)::numeric(24,8) reorder_point,current_stock<greatest(0,average_daily_demand*lead_time_days+safety_stock) below_rop,greatest(0,current_stock-greatest(0,average_daily_demand*lead_time_days+safety_stock))::numeric(24,8) surplus_above_rop from base;
create table if not exists public.routing_deficit_bypasses (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,location_id uuid not null references public.locations(id) on delete restrict,ingredient_id uuid not null references public.ingredients(id) on delete restrict,reason text not null,requested_quantity numeric(24,8) not null check(requested_quantity>0),unit text not null,created_at timestamptz not null default now());
create index if not exists idx_v20_bypass_business_time on public.routing_deficit_bypasses(business_id,created_at desc);
alter table public.routing_execution_logs enable row level security;
alter table public.routing_deficit_bypasses enable row level security;
drop policy if exists v20_routing_logs_select on public.routing_execution_logs;
create policy v20_routing_logs_select on public.routing_execution_logs for select using(is_member(business_id));
drop policy if exists v20_bypass_select on public.routing_deficit_bypasses;
create policy v20_bypass_select on public.routing_deficit_bypasses for select using(is_member(business_id));
revoke insert,update,delete on public.routing_execution_logs from authenticated;
revoke insert,update,delete on public.routing_deficit_bypasses from authenticated;
create or replace function public.v20_verify_tenant_route(p_business_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from businesses where id=p_business_id) then raise exception 'Business not found'; end if; if exists(select 1 from view_v20_location_reorder r where r.business_id=p_business_id and r.purchase_unit_exact=false and r.below_rop and r.cold_start=false) then return jsonb_build_object('ok',false,'reason','unit_mismatch_deficit_present'); end if; return jsonb_build_object('ok',true); end $$;
grant execute on function public.v20_verify_tenant_route(uuid) to authenticated;